import{c as e,Q as a,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Agentic Autonomy Levels","description":"","frontmatter":{"url":"https://x.com/addyosmani/status/2072885435312042327","title":"Agentic Autonomy Levels","author":"addyosmani","archived":"2026-07-03T00:00:00.000Z","handle":"@addyosmani","published":"2026-07-03T00:00:00.000Z","stats":"797 likes · 98 retweets · 1229 bookmarks · 383138 views","tags":["agentic-engineering","autonomy-levels","orchestration","anti-patterns","verification","agent-contract"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-03-@addyosmani-042327.md","filePath":"research/tweets/2026-07-03-@addyosmani-042327.md","lastUpdated":1785909234000}'),o={name:"research/tweets/2026-07-03-@addyosmani-042327.md"};function i(s,t,d,l,g,h){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="agentic-autonomy-levels-—-addyosmani" tabindex="-1">Agentic Autonomy Levels — @addyosmani <a class="header-anchor" href="#agentic-autonomy-levels-—-addyosmani" aria-label="Permalink to &quot;Agentic Autonomy Levels — @addyosmani&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/addyosmani/status/2072885435312042327" target="_blank" rel="noreferrer">https://x.com/addyosmani/status/2072885435312042327</a><strong>作者</strong>：addyosmani（@addyosmani） <strong>發布日期</strong>：2026-07-03 <strong>收錄日期</strong>：2026-07-03 <strong>類型</strong>：Twitter Article <strong>統計</strong>：797 likes · 98 retweets · 1229 bookmarks · 383138 views</p><hr><h2 id="全文摘要" tabindex="-1">全文摘要 <a class="header-anchor" href="#全文摘要" aria-label="Permalink to &quot;全文摘要&quot;">​</a></h2><p><strong>定位</strong>：Agentic Engineering 成熟框架：6 階自主等級（Agency × Orchestration 雙軸）、Agent 執行合約、四大反模式、自主風險評估三問，以及 Anthropic 400K session 數據。</p><h3 id="雙軸模型-agency-×-orchestration" tabindex="-1">雙軸模型：Agency × Orchestration <a class="header-anchor" href="#雙軸模型-agency-×-orchestration" aria-label="Permalink to &quot;雙軸模型：Agency × Orchestration&quot;">​</a></h3><p><strong>Agency 軸</strong>（單 agent 深度）：</p><ul><li>Low：建議候選動作，等待決策</li><li>Mid：執行任務，持續回報證據，可隨時調向</li><li>High：以目標驅動，實驗/學習/測試，自主到完成才回報</li></ul><p><strong>Orchestration 軸</strong>（多 agent 廣度）：</p><ul><li>Low：單 agent，單 thread</li><li>Mid：多 agent，各在獨立 worktree，目標相互隔離</li><li>High：Orchestrator 從 backlog/issue tracker 生成連續工作，只在失敗時介入（&quot;management by exception&quot;）</li></ul><h3 id="六個自主等級" tabindex="-1">六個自主等級 <a class="header-anchor" href="#六個自主等級" aria-label="Permalink to &quot;六個自主等級&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等級</th><th>名稱</th><th>核心特徵</th><th>驗證方式</th></tr></thead><tbody><tr><td>0</td><td>Assist</td><td>Autocomplete / inline 建議，人類決策</td><td>本地驗證</td></tr><tr><td>1</td><td>Supervised action</td><td>Agent 執行但每步需確認，預設姿態</td><td>Per-action approval</td></tr><tr><td>2</td><td>Scoped task delegation</td><td>明確目標+約束+完成定義，人近旁可中斷</td><td>自動化測試/截圖/類型</td></tr><tr><td>3</td><td>Goal-driven autonomy</td><td><code>/goal /loop /schedule</code>，直到條件達標</td><td>可量化的成功條件</td></tr><tr><td>4</td><td>Parallel delegation</td><td>多 agent 平行，各有獨立 worktree 和 review queue</td><td>所有權規則+合並控制</td></tr><tr><td>5</td><td>Managed-by-exception</td><td>Manager agent 分派、監控、驗證、重試、升級</td><td>獨立驗證者+跨層 gate</td></tr></tbody></table><p><strong>三個時代</strong>：駕駛座（0-1）→ 有界任務（2-3）→ 編排（4-5）</p><h3 id="⚠️-高自主系統三問" tabindex="-1">⚠️ 高自主系統三問 <a class="header-anchor" href="#⚠️-高自主系統三問" aria-label="Permalink to &quot;⚠️ 高自主系統三問&quot;">​</a></h3><blockquote><ol><li><strong>我們多快知道做錯了？</strong>（發現速度）</li><li><strong>我們多乾淨地能撤銷？</strong>（可逆性）</li><li><strong>什麼能證明我們是對的？</strong>（可驗證性）</li></ol></blockquote><p>若三個答案都是：不快、很困難、信任摘要 → 這不是真正的高自主。</p><h3 id="agent-執行合約-8-欄位" tabindex="-1">Agent 執行合約（8 欄位） <a class="header-anchor" href="#agent-執行合約-8-欄位" aria-label="Permalink to &quot;Agent 執行合約（8 欄位）&quot;">​</a></h3><p>每次 agent run 前應定義：</p><table tabindex="0"><thead><tr><th>欄位</th><th>說明</th></tr></thead><tbody><tr><td>Goal</td><td>要達成的結果（非活動、非技術手段，是結果）</td></tr><tr><td>Scope</td><td>操作域和允許的技術</td></tr><tr><td>Non-goals</td><td>目標以外的事項</td></tr><tr><td>Tools &amp; Permissions</td><td>Agent 與世界互動的方式</td></tr><tr><td>Stopping condition</td><td>何時停止（最好是可量化變數）</td></tr><tr><td>Evidence</td><td>可獨立確認任務完成的具體測試/截圖/日誌/數據庫記錄</td></tr><tr><td>Escalation</td><td>什麼情況涉及誰（包括誰運行 agent）</td></tr><tr><td>Budget</td><td>時間/effort/token 上限（可加嘗試次數和並行度限制）</td></tr></tbody></table><h3 id="四大反模式" tabindex="-1">四大反模式 <a class="header-anchor" href="#四大反模式" aria-label="Permalink to &quot;四大反模式&quot;">​</a></h3><p><strong>1. 自主性即地位（Autonomy as Status）</strong> 症狀：更高自主性被視為能力象徵，agent 跑得比驗證支撐的更熱。 修復：獎勵「選對自主等級」行為，而非「跑最高等級」。</p><p><strong>2. 許可清洗（Permission Laundering）</strong> 症狀：審批疲勞導致授予 agent 遠超必要的寬泛訪問權。 修復：沙盒 profile、scoped writable roots、allowlisted commands、hooks、Auto-review。</p><p><strong>3. 摘要替換（Summary Substitution）⚠️</strong> 症狀：Agent 的工作摘要替代了實際 review，假設摘要就夠了。 修復：驗證包要含 diff + 測試 + 日誌 + 截圖 + 審查發現 + 風險 + 缺口，<strong>不接受認知投降</strong>。</p><p><strong>4. 艦隊扮演（Fleet Cosplay）</strong> 症狀：幾十個 agent 並行，但人類仍手動協調所有依賴。 修復：共享狀態、所有權規則、依賴追蹤；縮小 WIP 迫使記錄協作步驟直到編排自動化。</p><h3 id="anthropic-400k-sessions-數據" tabindex="-1">Anthropic 400K Sessions 數據 <a class="header-anchor" href="#anthropic-400k-sessions-數據" aria-label="Permalink to &quot;Anthropic 400K Sessions 數據&quot;">​</a></h3><p>研究範圍：2025-10 至 2026-04，~400K sessions，~235K 用戶：</p><ul><li>人類做 ~70% 的<strong>規劃決策</strong></li><li>Claude 做 ~80% 的<strong>執行工作</strong></li><li>「高自主不是把人排除在外，而是從做每一步 → 決定下一個方向」</li></ul><h3 id="驗證始終是瓶頸" tabindex="-1">驗證始終是瓶頸 <a class="header-anchor" href="#驗證始終是瓶頸" aria-label="Permalink to &quot;驗證始終是瓶頸&quot;">​</a></h3><p><strong>「The bottlenecks are coordination, verification, maintenance, product judgment and incident learning.」</strong></p><p>建議追蹤的自主指標：</p><ul><li>介入間平均時間（Mean time between interventions）</li><li>最長無人值守成功 run（Longest successful unattended run）</li><li>沙盒 vs 升級比例</li><li>自動批准 vs 拒絕百分比</li><li>每個人類指令的 agent 動作數</li><li>每個接受變更的 review 時間</li><li>每個置信等級的返工率</li></ul><p><strong>「Verification will always be the bottleneck.」</strong></p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Agentic Engineering 最完整自主等級框架：6 等級 / 雙軸（Agency×Orchestration）/ 三個時代 / Agent 執行合約 8 欄位 / 四大反模式（Summary Substitution 最關鍵）/ 高自主三問 / Anthropic 400K session 數據；「驗證是永遠的瓶頸」。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>雙軸模型</strong>：單 agent 深度（Agency）與多 agent 廣度（Orchestration）是正交維度，一維梯子無法捕捉</li><li><strong>Summary Substitution 反模式</strong>：Agent 摘要 ≠ 驗證，必須要求證據包（diff/tests/logs/screenshots）</li><li><strong>三問框架</strong>：「多快知錯 / 多乾淨撤銷 / 什麼能證明對」是真正高自主的可行驗證標準</li><li><strong>人類在高自主中的角色</strong>：從做每一步 → 決定下一個方向（70% 規劃 / 80% 執行由 Claude）</li><li><strong>Fleet cosplay 陷阱</strong>：有多個 agent 但沒有真正的所有權/狀態管理 = 假 orchestration</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Anthropic 研究：~400K sessions, ~235K 用戶（Oct 2025–Apr 2026）</li><li>人類 70% 規劃 / Claude 80% 執行</li><li>6 等級 × 8 欄位 Agent 合約（結構化 handoff）</li><li>自主度量指標清單（8 項）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>Summary Substitution 與 workspace 的 unverified_success 閘門完全對齊，是本文最直接的規則強化</li><li>Agent 執行合約（8 欄位）是 delegation-protocol.md 的高品質補充</li><li>雙軸模型給「委派決策」增加了正交性分析（單 agent 深度 vs 多 agent 廣度）</li><li>400K sessions 數據是本批次 19 篇文章中唯一的大規模實證數據</li><li>文章明確標注「100% human-written」（Pangram 驗證），可信度高</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7.5/10</td><td>8 欄位合約補充 task-templates；4 反模式補充 subagent-strategy；3 問框架補充 judgment-rubrics</td></tr><tr><td>B. 創新性 (20%)</td><td>8.5/10</td><td>雙軸模型是真正新框架；Fleet cosplay/Permission laundering 命名精準；指標體系新穎</td></tr><tr><td>C. 證據品質 (20%)</td><td>8.5/10</td><td>400K session Anthropic 數據；3 問框架從第一性原理推導；人工標注驗證</td></tr><tr><td>D. 技術深度 (15%)</td><td>8.5/10</td><td>Level 4/5 具體失敗模式；所有權規則設計；WIP 限制策略</td></tr><tr><td>E. 泛化性 (15%)</td><td>9/10</td><td>跨工具/跨語言的通用自主框架；不 Claude 特定</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.3/10</strong></td><td>7.5×0.3+8.5×0.2+8.5×0.2+8.5×0.15+9×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：8 欄位 Agent 合約補充 delegation-protocol.md task-templates；Summary Substitution 反模式強化 core.md §TEST unverified_success 閘門；4 反模式清單補充 subagent-strategy.md；高自主三問補充 judgment-rubrics.md。</p>',45)])])}const m=e(o,[["render",i]]);export{u as __pageData,m as default};
